const NO_GERADOR = 'Gerador'; // nome do nó Code que gerou as grades candidatas

const resposta = $input.first().json;
const gerador = $(NO_GERADOR).first().json;
const candidatas = gerador.candidatas || [];
const candidatasParaIA = gerador.candidatasParaIA || [];
const familias = gerador.familias || [];
const maxPorFamilia = gerador.maxOpcoesPorFamilia || 3;

const avisos = [];

// 1. Achar o texto da resposta.
function acharTexto(obj) {
  const caminhos = [
    obj && obj.content && obj.content.parts,
    obj && obj.candidates && obj.candidates[0] && obj.candidates[0].content && obj.candidates[0].content.parts,
  ];
  for (const parts of caminhos) {
    if (Array.isArray(parts)) {
      const t = parts.map(p => (p && p.text) || '').join('');
      if (t.trim()) return t;
    }
  }
  for (const k of ['output', 'text', 'response', 'message']) {
    if (obj && typeof obj[k] === 'string' && obj[k].trim()) return obj[k];
  }
  const buscar = v => {
    if (typeof v === 'string') return v.includes('opcoes') ? v : null;
    if (v && typeof v === 'object') {
      for (const x of Object.values(v)) {
        const r = buscar(x);
        if (r) return r;
      }
    }
    return null;
  };
  return buscar(obj);
}

// 2. Ler o JSON, mesmo com cercas de markdown ou texto em volta.
function lerJson(texto) {
  if (!texto) return null;
  let t = String(texto).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(t); } catch (e) { /* tenta o recorte abaixo */ }
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { /* sem JSON válido */ }
  }
  return null;
}

// 3. Validar as opções por família.
const texto = acharTexto(resposta);
const json = lerJson(texto);
const opcoes = [];
let origem = 'ia';

if (!json || !Array.isArray(json.opcoes)) {
  avisos.push('A resposta da IA não pôde ser lida como JSON com "opcoes"; foram usadas opções automáticas');
} else {
  const usadas = new Set();
  const porFamilia = {};
  for (const o of json.opcoes) {
    const c = Number(o && o.candidata);
    if (!Number.isInteger(c) || c < 0 || c >= candidatas.length) {
      avisos.push(`Opção ignorada: candidata "${o && o.candidata}" não existe`);
      continue;
    }
    if (usadas.has(c)) {
      avisos.push(`Opção ignorada: a candidata ${c} apareceu repetida`);
      continue;
    }
    const f = candidatas[c].familia;
    if ((porFamilia[f] || 0) >= maxPorFamilia) {
      avisos.push(`Opção ignorada: a candidata ${c} passa do máximo de ${maxPorFamilia} opções da combinação ${f}`);
      continue;
    }
    usadas.add(c);
    porFamilia[f] = (porFamilia[f] || 0) + 1;
    opcoes.push({
      candidata: c,
      familia: f,
      titulo: String((o && o.titulo) || '').trim(),
      resumo: String((o && o.resumo) || '').trim(),
      tradeoffs: String((o && o.tradeoffs) || '').trim(),
    });
  }
}

// 4. Plano B: texto automático a partir das métricas.
function automatica(indice) {
  const c = candidatasParaIA[indice] || {};
  const m = c.metricas || {};
  const dias = (m.diasComAula || []).join(', ');
  const partes = [`${m.materias} matéria(s), aulas das ${m.primeiraAula} às ${m.ultimaAula}`];
  if (dias) partes.push(`dias com aula: ${dias}`);
  partes.push(m.janelasMinutos ? `${m.janelasMinutos} min de janelas entre as aulas` : 'sem janelas entre as aulas');
  return { candidata: indice, familia: c.familia, titulo: '', resumo: partes.join('. ') + '.', tradeoffs: '' };
}

// Completa cada família até o máximo de opções (as escolhas da IA sempre ficam; o código só preenche o que faltou,
// usando as melhores grades ainda não escolhidas da própria família).
const temIA = opcoes.length > 0;
if (temIA === false) origem = 'automatico';
let acrescentou = false;
for (const f of familias) {
  const alvo = Math.min(f.maxOpcoes || maxPorFamilia, f.candidatas.length);
  const daFamilia = opcoes.filter(o => o.familia === f.familia).length;
  const livres = f.candidatas.filter(c => !opcoes.some(o => o.candidata === c));
  const precisa = Math.max(0, alvo - daFamilia);
  for (const c of livres.slice(0, precisa)) {
    opcoes.push(automatica(c));
    acrescentou = true;
  }
  if (temIA && precisa) {
    avisos.push(daFamilia
      ? `A IA escolheu ${daFamilia} grade(s) da combinação ${f.familia}; o código completou até ${alvo}`
      : `A IA não escolheu nenhuma grade da combinação ${f.familia}; foram acrescentadas as melhores opções dela`);
  }
}
if (temIA && acrescentou) origem = 'ia+automatico';
opcoes.sort((a, b) => a.familia - b.familia);

return [{ json: {
  opcoes,
  origemOpcoes: origem,
  validacaoAvisos: avisos,
  temOpcoes: opcoes.length > 0,
  candidatas,
  familias,
  estagio: gerador.estagio || [],
  tempos: gerador.tempos || [],
  emailAluno: gerador.emailAluno || '',
  prioridadesTexto: gerador.prioridadesTexto || [],
  evitarTexto: gerador.evitarTexto || [],
  observacoes: gerador.observacoes || '',
  avisosAluno: gerador.avisosAluno || [],
  // Problemas das etapas anteriores, para o e-mail explicar quando não há nenhuma grade possível.
  problemas: [...(gerador.preparoErros || []), ...(gerador.geradorErros || []), ...(gerador.preparoAvisos || []), ...(gerador.geradorAvisos || [])],
} }];

const MAX_POOL_POR_FAMILIA = 6;   // grades que o Gemini pode escolher em cada família
const MAX_OPCOES_POR_FAMILIA = 3; // máximo que o aluno recebe de cada família
const MAX_FAMILIAS = 5;
const MAX_TOTAL_OPCOES = 9;       // teto de grades no e-mail e no arquivo
const LIMITE_COMBINACOES = 200000;
const PESO_BUSCA = { obrigatoria: 1000, preferida: 1, opcional: 1 }; // o que a busca maximiza: obrigatórias, depois quantidade
const PESO_ORDEM = { obrigatoria: 100, preferida: 10, opcional: 1 };   // como as famílias são ordenadas

const HORA_CEDO = 9 * 60;    // "evitar aulas antes das 9h"
const HORA_NOITE = 18 * 60;  // "evitar aulas depois das 18h"
const JANELA_LONGA = 90;     // "evitar janelas longas": mais de 90 minutos entre duas aulas

// Diferença mínima entre duas grades da mesma família (basta uma delas valer):
const DIF_JANELAS = 60;  // minutos de janela
const DIF_HORARIO = 60;  // primeira ou última aula
const DIF_CARGA = 90;    // diferença de carga entre os dias (a diferença, não a carga)

const DIAS_UTEIS = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex'];
const ORDEM_DIAS = [...DIAS_UTEIS, 'Sáb'];
const TEXTO_EVITAR = { cedo9: 'aulas antes das 9h', noite18: 'aulas depois das 18h', janelasLongas: 'janela longa entre aulas (mais de 90 min)' };

const item = $input.first().json;
const materias = item.materias || [];
const restricoes = item.restricoes || [];
const tempos = item.tempos || [];
const prioridades = item.prioridades || [];
const evitar = item.evitar || [];

const erros = [];
const avisos = [];
const avisosAluno = [];

const fmt = min => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');
const conflita = (a, b) => a.dia === b.dia && a.inicio < b.fim && b.inicio < a.fim;
const conflitaTurmas = (a, b) => a.blocos.some(x => b.blocos.some(y => conflita(x, y)));

// ------------------------------------------------------------- 1. Turmas que cabem
const lista = [];
for (const m of materias) {
  let validas = m.opcoes.filter(o => !o.blocos.some(b => restricoes.some(r => conflita(b, r))));
  let motivo = 'todas as turmas conflitam com os seus compromissos';
  if (m.turmaPreferida && m.seNaoCouber === 'fora') {
    const preferida = validas.filter(o => o.rotulo === m.turmaPreferida);
    if (validas.length && !preferida.length) motivo = `a turma preferida (${m.turmaPreferida}) conflita com os seus compromissos e você pediu para deixar a matéria de fora nesse caso`;
    validas = preferida;
  }
  if (!validas.length) {
    avisos.push(`${m.nome}: ${motivo}`);
    avisosAluno.push(`${m.prioridade === 'obrigatoria' ? 'A matéria obrigatória ' : 'A matéria '}${m.nome} não entrou em nenhuma grade: ${motivo}.`);
    continue;
  }
  lista.push({ ...m, validas, peso: PESO_BUSCA[m.prioridade] || 1, pesoOrdem: PESO_ORDEM[m.prioridade] || PESO_ORDEM.preferida });
}

// Pares de matérias totalmente incompatíveis (toda turma de uma bate com toda turma da outra).
const incompativeis = {};
for (const x of lista) {
  incompativeis[x.nome] = lista.filter(y => y !== x && x.validas.every(tx => y.validas.every(ty => conflitaTurmas(tx, ty)))).map(y => y.nome);
}

// ------------------------------------------------------------------ 2. Busca
// Para cada matéria: escolhe uma turma ou deixa a matéria de fora. Guarda só as combinações de maior peso de busca.
const n = lista.length;
const sufixo = new Array(n + 1).fill(0);
for (let i = n - 1; i >= 0; i--) sufixo[i] = sufixo[i + 1] + lista[i].peso;

let melhor = -1;
let resultados = [];
let contador = 0;
let estourou = false;

function busca(i, escolhidas, blocos, peso) {
  if (estourou || peso + sufixo[i] < melhor) return;
  if (i === n) {
    if (++contador > LIMITE_COMBINACOES) { estourou = true; return; }
    if (peso > melhor) { melhor = peso; resultados = []; }
    resultados.push(escolhidas.slice());
    return;
  }
  for (const o of lista[i].validas) {
    if (o.blocos.some(b => blocos.some(c => conflita(b, c)))) continue;
    escolhidas.push({ materia: lista[i], opcao: o });
    busca(i + 1, escolhidas, blocos.concat(o.blocos), peso + lista[i].peso);
    escolhidas.pop();
  }
  busca(i + 1, escolhidas, blocos, peso);
}

if (!materias.length) erros.push('Nenhuma matéria foi informada');
else if (!n) erros.push('Nenhuma matéria cabe nos seus compromissos');
else busca(0, [], [], 0);
if (estourou) avisos.push('Há combinações demais; as grades vêm de uma amostra delas');

// -------------------------------------------------------------- 3. Famílias
const grupos = new Map();
for (const r of resultados) {
  const dentro = new Set(r.map(e => e.materia.nome));
  const fora = lista.map(m => m.nome).filter(nome => !dentro.has(nome));
  const chave = fora.join('|');
  if (!grupos.has(chave)) grupos.set(chave, { foraDe: fora, pesoOrdem: lista.filter(m => dentro.has(m.nome)).reduce((soma, m) => soma + m.pesoOrdem, 0), grades: [] });
  grupos.get(chave).grades.push(r);
}

// Métricas de uma grade (r = [{ materia, opcao }]).
function analisar(r) {
  const porDia = {};
  for (const e of r) for (const b of e.opcao.blocos) (porDia[b.dia] = porDia[b.dia] || []).push(b);

  const janelasPorDia = {};
  const minutosDeAulaPorDia = {};
  let janelas = 0;
  let janelaMaxima = 0;
  let primeiro = Infinity;
  let ultimo = 0;
  let antes9 = 0;
  let depois18 = 0;
  for (const [d, aulas] of Object.entries(porDia)) {
    aulas.sort((a, b) => a.inicio - b.inicio);
    let j = 0;
    let total = 0;
    aulas.forEach((b, k) => {
      total += b.fim - b.inicio;
      if (k > 0) {
        const vao = Math.max(0, b.inicio - aulas[k - 1].fim);
        j += vao;
        janelaMaxima = Math.max(janelaMaxima, vao);
      }
      primeiro = Math.min(primeiro, b.inicio);
      ultimo = Math.max(ultimo, b.fim);
      antes9 += Math.max(0, Math.min(b.fim, HORA_CEDO) - b.inicio);
      depois18 += Math.max(0, b.fim - Math.max(b.inicio, HORA_NOITE));
    });
    janelasPorDia[d] = j;
    minutosDeAulaPorDia[d] = total;
    janelas += j;
  }
  const cargas = Object.values(minutosDeAulaPorDia);

  const atendidas = [];
  const naoAtendidas = [];
  for (const e of r) {
    if (!e.materia.turmaPreferida) continue;
    const horarios = e.opcao.blocos.map(b => `${b.dia} ${fmt(b.inicio)}`).join(', ');
    const texto = `${e.materia.nome}: turma preferida${e.opcao.professor ? ' (' + e.opcao.professor + ', ' + horarios + ')' : ''}`;
    (e.opcao.rotulo === e.materia.turmaPreferida ? atendidas : naoAtendidas).push(
      e.opcao.rotulo === e.materia.turmaPreferida ? texto : `${e.materia.nome}: foi usada outra turma, a preferida não coube com as demais`);
  }
  const violado = [];
  if (evitar.includes('cedo9') && antes9 > 0) violado.push('cedo9');
  if (evitar.includes('noite18') && depois18 > 0) violado.push('noite18');
  if (evitar.includes('janelasLongas') && janelaMaxima > JANELA_LONGA) violado.push('janelasLongas');

  return {
    materias: r.length,
    diasComAula: ORDEM_DIAS.filter(d => porDia[d]),
    diasLivres: DIAS_UTEIS.filter(d => !porDia[d]),
    janelasMinutos: janelas,
    janelasPorDia,
    minutosDeAulaPorDia,
    diferencaCargaMinutos: cargas.length ? Math.max(...cargas) - Math.min(...cargas) : 0,
    primeiraAula: fmt(primeiro),
    ultimaAula: fmt(ultimo),
    _ini: primeiro,
    _fim: ultimo,
    _atendidas: atendidas,
    _naoAtendidas: naoAtendidas,
    _violado: violado,
  };
}

// Critérios de escolha: primeiro as preferências e o que evitar, depois o critério da vez.
const antesDe = (a, b) => b.m._atendidas.length - a.m._atendidas.length || a.m._violado.length - b.m._violado.length;
const CRITERIOS = {
  janelas: (a, b) => a.m.janelasMinutos - b.m.janelasMinutos || b.m.diasLivres.length - a.m.diasLivres.length,
  diasLivres: (a, b) => b.m.diasLivres.length - a.m.diasLivres.length || a.m.janelasMinutos - b.m.janelasMinutos,
  carga: (a, b) => a.m.diferencaCargaMinutos - b.m.diferencaCargaMinutos || a.m.janelasMinutos - b.m.janelasMinutos,
  cedo: (a, b) => a.m._fim - b.m._fim || a.m.janelasMinutos - b.m.janelasMinutos,
  tarde: (a, b) => b.m._ini - a.m._ini || a.m.janelasMinutos - b.m.janelasMinutos,
};
// As prioridades do aluno entram primeiro e de novo no fim, ganhando mais vagas; os demais critérios continuam presentes.
const PADRAO = Object.keys(CRITERIOS);
const sequencia = [...prioridades, ...PADRAO.filter(c => !prioridades.includes(c)), ...prioridades];

const diferentes = (a, b) =>
  a.m.diasLivres.join() !== b.m.diasLivres.join() ||
  Math.abs(a.m.janelasMinutos - b.m.janelasMinutos) >= DIF_JANELAS ||
  Math.abs(a.m._ini - b.m._ini) >= DIF_HORARIO ||
  Math.abs(a.m._fim - b.m._fim) >= DIF_HORARIO ||
  Math.abs(a.m.diferencaCargaMinutos - b.m.diferencaCargaMinutos) >= DIF_CARGA;

function montarPool(grades) {
  const analisadas = grades.map(r => ({ r, m: analisar(r) }));
  const pool = [];
  let avancou = true;
  while (pool.length < MAX_POOL_POR_FAMILIA && avancou) {
    avancou = false;
    for (const criterio of sequencia) {
      if (pool.length >= MAX_POOL_POR_FAMILIA) break;
      const cmp = (a, b) => antesDe(a, b) || CRITERIOS[criterio](a, b);
      let prox = null;
      for (const x of analisadas) {
        if (pool.includes(x) || !pool.every(p => diferentes(p, x))) continue;
        if (!prox || cmp(x, prox) < 0) prox = x;
      }
      if (prox) { pool.push(prox); avancou = true; }
    }
  }
  return pool;
}

let familias = [...grupos.values()].map(g => ({ foraDe: g.foraDe, pesoOrdem: g.pesoOrdem, totalDeGrades: g.grades.length, pool: montarPool(g.grades) }));
familias.sort((a, b) => b.pesoOrdem - a.pesoOrdem || antesDe(a.pool[0], b.pool[0]) || a.foraDe.join().localeCompare(b.foraDe.join()));
if (familias.length > MAX_FAMILIAS) {
  avisos.push(`Há ${familias.length} combinações de matérias possíveis; foram mantidas as ${MAX_FAMILIAS} primeiras`);
  avisosAluno.push(`Existem outras combinações de matérias além das mostradas (${familias.length} no total); marque prioridades para ver as que mais importam.`);
  familias = familias.slice(0, MAX_FAMILIAS);
}
const maxOpcoesPorFamilia = familias.length ? Math.max(1, Math.min(MAX_OPCOES_POR_FAMILIA, Math.floor(MAX_TOTAL_OPCOES / familias.length))) : 0;

for (const f of familias) {
  for (const nome of f.foraDe) {
    const m = lista.find(x => x.nome === nome);
    if (m && m.prioridade === 'obrigatoria') avisosAluno.push(`Não foi possível incluir a matéria obrigatória ${nome} em uma das combinações.`);
  }
}

// ----------------------------------------------------------------- 4. Saída
const candidatas = [];
const candidatasParaIA = [];
const familiasSaida = familias.map((f, fi) => {
  const indices = [];
  for (const { r, m } of f.pool) {
    const indice = candidatas.length;
    indices.push(indice);
    candidatas.push({
      familia: fi,
      foraDe: f.foraDe,
      materias: r.map(e => ({ nome: e.materia.nome, codigo: e.opcao.professor || '', blocos: e.opcao.blocos.map(b => ({ dia: b.dia, inicio: b.inicio, fim: b.fim })) })),
      preferenciasAtendidas: m._atendidas,
      preferenciasNaoAtendidas: m._naoAtendidas,
      evitarNaoEvitado: m._violado.map(c => TEXTO_EVITAR[c]),
    });
    const { _ini, _fim, _atendidas, _naoAtendidas, _violado, ...metricas } = m;
    candidatasParaIA.push({
      indice,
      familia: fi,
      materias: r.map(e => ({
        nome: e.materia.nome,
        professor: e.opcao.professor || '',
        aulas: e.opcao.blocos.map(b => ({ dia: b.dia, inicio: fmt(b.inicio), fim: fmt(b.fim) })),
      })),
      metricas,
      preferenciasAtendidas: _atendidas,
      preferenciasNaoAtendidas: _naoAtendidas,
      evitarNaoEvitado: _violado.map(c => TEXTO_EVITAR[c]),
    });
  }
  return {
    familia: fi,
    incluidas: f.pool[0].r.map(e => e.materia.nome),
    foraDe: f.foraDe,
    pesoPrioridade: f.pesoOrdem,
    incompativeis: Object.fromEntries(f.foraDe.map(nome => [nome, incompativeis[nome] || []])),
    totalDeGrades: f.totalDeGrades,
    maxOpcoes: maxOpcoesPorFamilia,
    candidatas: indices,
  };
});

const compromissosParaIA = restricoes.map(r => ({ dia: r.dia, inicio: fmt(r.inicio), fim: fmt(r.fim) }));

return [{ json: {
  ...item,
  candidatas,
  candidatasParaIA,
  familias: familiasSaida,
  maxOpcoesPorFamilia,
  compromissosParaIA,
  estagio: restricoes,
  duracaoTempo: tempos.length ? tempos[0].fim - tempos[0].inicio : null,
  inicioPrimeiroTempo: tempos.length ? fmt(tempos[0].inicio) : '',
  avisosAluno,
  geradorErros: erros,
  geradorAvisos: avisos,
} }];

const NO_FORMULARIO = 'Informações Iniciais'; // Form Trigger (e-mail, início e duração dos tempos)
const NO_BLOQUEIOS = 'Bloqueios';             // página com um campo de texto por dia da semana
const NO_MATERIA = 'Matéria';                 // páginas de matéria: Matéria, Matéria1, Matéria2, ...
const MAX_MATERIAS = 6;                       // quantas páginas de matéria existem no formulário
const DESLOCAMENTO_ANTES = 60;                // minutos bloqueados ANTES de cada compromisso
const PADRAO = { duracao: 50, inicio: '07:00', fim: '22:00' }; // usados se o campo não existir ou ficar vazio

const item = $input.first().json;
const erros = [];
const avisos = [];

const ler = nome => { try { return $(nome).first().json; } catch (e) { return null; } }; // null = página não exibida
const norm = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const fmt = min => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');

// Hora com minutos opcionais: 14, 14h, 14:30, 14h30. Intervalo: 14-16, 14h às 16h30...
const HORA = '(\\d{1,2})(?:\\s*(?::|h)\\s*(\\d{2}))?\\s*h?';
const INTERVALO = new RegExp(`^${HORA}\\s*(?:-|–|—|a|às|até)\\s*${HORA}$`, 'i');

// Converte um intervalo em { inicio, fim } (minutos) ou { erro }.
function intervalo(texto) {
  const m = texto.match(INTERVALO);
  if (!m) return { erro: 'está em formato inválido. Use, por exemplo: 14:30-16:10' };
  const inicio = Number(m[1]) * 60 + Number(m[2] || 0);
  const fim = Number(m[3]) * 60 + Number(m[4] || 0);
  if (Number(m[2] || 0) > 59 || Number(m[4] || 0) > 59 || inicio >= fim || fim > 1440) {
    return { erro: 'é um horário inválido (minutos de 00 a 59, início menor que o fim, até 24:00)' };
  }
  return { inicio, fim };
}

// ---------------------------------------------------------------- Tempos
const inicial = ler(NO_FORMULARIO) || item;
const chaves = Object.keys(inicial).filter(k => k !== 'submittedAt' && k !== 'formMode');
const usadas = new Set();
const achar = padroes => {
  for (const p of padroes) {
    const k = chaves.find(c => !usadas.has(c) && p.test(norm(c)));
    if (k) { usadas.add(k); return k; }
  }
  return null;
};
const vazio = v => v === undefined || v === null || String(v).trim() === '' || typeof v === 'object';

// Prioridades, o que evitar e observações (opcionais). São reservados antes dos campos dos tempos, para que um
// texto como "não quero aula no primeiro tempo" não seja confundido com o horário do primeiro tempo.
const kPrior = achar([/priori/]);
const kEvitar = achar([/evit/]);
const kObs = achar([/observ/]);
const marcados = chave => {
  const v = chave === null ? [] : inicial[chave];
  return (Array.isArray(v) ? v : String(v ?? '').split(/[,;\n]/)).map(x => String(x).trim()).filter(Boolean);
};
const codigos = (lista, regras) => [...new Set(lista.map(t => { const r = regras.find(([, re]) => re.test(norm(t))); return r ? r[0] : null; }).filter(Boolean))];
const prioridadesTexto = marcados(kPrior);
const evitarTexto = marcados(kEvitar);
const prioridades = codigos(prioridadesTexto, [['janelas', /janela/], ['diasLivres', /dias? livre/], ['carga', /carga|equilibr/], ['cedo', /terminar|cedo/], ['tarde', /comecar|tarde/]]);
const evitar = codigos(evitarTexto, [['cedo9', /antes/], ['noite18', /depois|noite/], ['janelasLongas', /janela/]]);
const observacoes = kObs && !vazio(inicial[kObs]) ? String(inicial[kObs]).trim() : '';
for (const [lista, codigosLista, nome] of [[prioridadesTexto, prioridades, 'prioridade'], [evitarTexto, evitar, 'evitar']]) {
  if (lista.length > codigosLista.length) avisos.push(`Primeira página: alguma opção de ${nome} não foi reconhecida (recebido: ${lista.join(' | ')})`);
}

const kDuracao = achar([/durac/, /minut/, /cada (tempo|aula)/]);
const kFim = achar([/termin/, /ultimo/, /\bfim\b/, /encerr/]);
const kInicio = achar([/primeir/, /inicio/, /comec/]);
const kEmail = chaves.find(c => /mail/.test(norm(c)));

function valorDe(chave, padrao, descricao) {
  if (chave === null || vazio(inicial[chave])) {
    avisos.push(chave === null
      ? `Tempos: nenhum campo de ${descricao} foi encontrado; usando o padrão (${padrao}). Campos recebidos: ${chaves.join(' | ') || '(nenhum)'}`
      : `Tempos: o campo "${chave}" está vazio; usando o padrão (${padrao})`);
    return padrao;
  }
  return inicial[chave];
}

const brutaDuracao = valorDe(kDuracao, PADRAO.duracao, 'duração dos tempos');
const numero = String(brutaDuracao).match(/\d+/);
const duracao = numero ? Number(numero[0]) : NaN;
if (!Number.isInteger(duracao) || duracao < 10 || duracao > 240) {
  erros.push(`Tempos: a duração deve ser um número inteiro de minutos entre 10 e 240 (recebido: "${brutaDuracao}")`);
}

const horaDe = (texto, rotulo) => {
  const m = String(texto).trim().match(/^\D*(\d{1,2})(?:\s*(?::|h)\s*(\d{2}))?/i);
  const min = m ? Number(m[1]) * 60 + Number(m[2] || 0) : NaN;
  if (!m || Number(m[2] || 0) > 59 || min > 1440) { erros.push(`Tempos: ${rotulo} "${texto}" não é um horário válido. Use, por exemplo, 07:00`); return null; }
  return min;
};
const iniMin = horaDe(valorDe(kInicio, PADRAO.inicio, 'horário do primeiro tempo'), 'o horário do primeiro tempo');
// O horário do último tempo é opcional na primeira página: sem o campo, usa o padrão sem avisar.
const fimMin = horaDe(kFim === null || vazio(inicial[kFim]) ? PADRAO.fim : inicial[kFim], 'o horário final');
if (iniMin !== null && fimMin !== null && iniMin >= fimMin) erros.push(`Tempos: o horário final (${fmt(fimMin)}) deve ser depois do primeiro tempo (${fmt(iniMin)})`);

const tempos = [];
if (!erros.length) {
  for (let t = iniMin, n = 1; t + duracao <= fimMin; t += duracao, n++) tempos.push({ n, inicio: t, fim: t + duracao, rotulo: `${fmt(t)}–${fmt(t + duracao)}` });
  if (!tempos.length) erros.push('Tempos: nenhum tempo cabe entre o primeiro horário e o fim informado');
}

// ------------------------------------------------------------ Restrições
// Um campo por dia. O rótulo pode ser Segunda, Segunda-feira, Segunda:... (sem depender de acento ou maiúsculas).
const DIAS_BLOQUEIO = [['segunda', 'Seg'], ['terca', 'Ter'], ['quarta', 'Qua'], ['quinta', 'Qui'], ['sexta', 'Sex'], ['sabado', 'Sáb']];
const bloqueios = ler(NO_BLOQUEIOS);
const brutos = [];
let diasEncontrados = 0;

for (const [palavra, dia] of DIAS_BLOQUEIO) {
  const chave = Object.keys(bloqueios || {}).find(k => norm(k).startsWith(palavra));
  if (chave === undefined) continue;
  diasEncontrados++;
  for (const parte of String(bloqueios[chave] ?? '').trim().split(/\s*(?:[,;\n]|\be\b)\s*/i)) {
    if (!parte) continue;
    const r = intervalo(parte);
    if (r.erro) { erros.push(`Bloqueios, ${chave} "${parte}" ${r.erro}`); continue; }
    brutos.push({ dia, inicio: Math.max(0, r.inicio - DESLOCAMENTO_ANTES), fim: r.fim });
  }
}
if (!diasEncontrados) {
  avisos.push(`Bloqueios: nenhum campo de dia foi encontrado. O nó "${NO_BLOQUEIOS}" ${bloqueios ? 'existe, mas sem campos de dia' : 'não foi encontrado'}; confira o nome em NO_BLOQUEIOS.`);
} else if (!brutos.length && !erros.some(e => e.startsWith('Bloqueios'))) {
  avisos.push('Bloqueios: todos os campos estão vazios; nenhum compromisso será considerado.');
}

// Junta blocos do mesmo dia que se sobrepõem ou se encostam.
const restricoes = [];
brutos.sort((a, b) => DIAS_BLOQUEIO.findIndex(d => d[1] === a.dia) - DIAS_BLOQUEIO.findIndex(d => d[1] === b.dia) || a.inicio - b.inicio);
for (const b of brutos) {
  const ultimo = restricoes[restricoes.length - 1];
  if (ultimo && ultimo.dia === b.dia && b.inicio <= ultimo.fim) ultimo.fim = Math.max(ultimo.fim, b.fim);
  else restricoes.push({ ...b });
}

// --------------------------------------------------------------- Matérias
// Cada página é uma matéria; cada campo "Opção N:" é uma turma:  Matéria;Professor;Dia;Horário[;Dia;Horário]
const DIAS = { seg: 'Seg', ter: 'Ter', qua: 'Qua', qui: 'Qui', sex: 'Sex', sab: 'Sáb' };

function lerOpcao(texto) {
  const partes = texto.split(';').map(p => p.trim());
  while (partes.length && partes[partes.length - 1] === '') partes.pop();
  if (partes.length < 4 || (partes.length - 2) % 2 !== 0) {
    return { erro: `"${texto}" está fora do formato Matéria;Professor;Dia;Horário (repita Dia;Horário para mais dias)` };
  }
  const [nome, professor, ...resto] = partes;
  if (!nome) return { erro: 'o nome da matéria está vazio' };

  const blocos = [];
  for (let i = 0; i < resto.length; i += 2) {
    const dia = DIAS[norm(resto[i]).slice(0, 3)];
    if (!dia) return { erro: `dia "${resto[i]}" não reconhecido (use Seg, Ter, Qua, Qui ou Sex)` };
    const r = intervalo(resto[i + 1]);
    if (r.erro) return { erro: `horário "${resto[i + 1]}" ${r.erro}` };
    blocos.push({ dia, inicio: r.inicio, fim: r.fim });
  }
  const conflito = blocos.some((a, i) => blocos.some((b, j) => j > i && a.dia === b.dia && a.inicio < b.fim && b.inicio < a.fim));
  return conflito ? { erro: 'dois horários se sobrepõem no mesmo dia' } : { nome, professor, blocos };
}

const materias = [];
for (let k = 0; k < MAX_MATERIAS; k++) {
  const pagina = NO_MATERIA + (k ? k : '');
  const dados = ler(pagina);
  if (!dados) continue; // página que o aluno não chegou a ver (marcou "Finalizar" antes)

  // Campos opcionais da página: prioridade da matéria, turma preferida e o que fazer se ela não couber.
  const outros = Object.keys(dados).filter(k => !/^opcao \d/.test(norm(k)) && !/finalizar/.test(norm(k)));
  const kSeNao = outros.find(k => /couber/.test(norm(k)));
  const kTurma = outros.find(k => k !== kSeNao && /prefer/.test(norm(k)));
  const kPrio = outros.find(k => k !== kSeNao && k !== kTurma && /priori/.test(norm(k)));
  const textoDe = k => (k === undefined ? '' : norm(dados[k] ?? ''));
  const prioridade = /obrig/.test(textoDe(kPrio)) ? 'obrigatoria' : /opcion/.test(textoDe(kPrio)) ? 'opcional' : 'preferida';
  const numeroTurma = (textoDe(kTurma).match(/\d/) || [])[0];
  const seNaoCouber = /fora|deix/.test(textoDe(kSeNao)) ? 'fora' : 'aceitar';

  let nome = null;
  const opcoes = [];
  for (let n = 1; n <= 5; n++) {
    const campo = `Opção ${n}:`;
    const texto = String(dados[campo] ?? '').trim();
    if (!texto) continue;
    const r = lerOpcao(texto);
    if (r.erro) { erros.push(`${pagina}, ${campo} ${r.erro}`); continue; }
    if (nome === null) nome = r.nome;
    else if (norm(r.nome) !== norm(nome)) avisos.push(`${pagina}, ${campo} o nome "${r.nome}" é diferente de "${nome}"; foi usado "${nome}"`);
    opcoes.push({ rotulo: `Opção ${n}`, professor: r.professor, blocos: r.blocos });
  }
  let turmaPreferida = null;
  if (numeroTurma) {
    turmaPreferida = `Opção ${numeroTurma}`;
    if (!opcoes.some(o => o.rotulo === turmaPreferida)) {
      avisos.push(`${pagina}: a turma preferida (${turmaPreferida}) não foi preenchida ou é inválida; a preferência foi ignorada`);
      turmaPreferida = null;
    }
  }
  if (opcoes.length) materias.push({ pagina, nome, opcoes, prioridade, turmaPreferida, seNaoCouber });
  else erros.push(`${pagina}: nenhuma opção válida foi preenchida`);
}

return [{ json: {
  ...item,
  emailAluno: kEmail ? String(inicial[kEmail]).trim() : '',
  tempos,
  restricoes,
  materias,
  prioridades,
  prioridadesTexto,
  evitar,
  evitarTexto,
  observacoes,
  preparoErros: erros,
  preparoAvisos: avisos,
} }];

const NO_GERADOR = 'Gerador'; // nome do nó Code que gerou as grades candidatas

const resposta = $input.first().json;
const gerador = $(NO_GERADOR).first().json;
const candidatas = gerador.candidatas || [];
const candidatasParaIA = gerador.candidatasParaIA || [];
const familias = gerador.familias || [];
const maxPorFamilia = gerador.maxOpcoesPorFamilia || 3;

const avisos = [];

// 1. Achar o texto da resposta.
function acharTexto(obj) {
  const caminhos = [
    obj && obj.content && obj.content.parts,
    obj && obj.candidates && obj.candidates[0] && obj.candidates[0].content && obj.candidates[0].content.parts,
  ];
  for (const parts of caminhos) {
    if (Array.isArray(parts)) {
      const t = parts.map(p => (p && p.text) || '').join('');
      if (t.trim()) return t;
    }
  }
  for (const k of ['output', 'text', 'response', 'message']) {
    if (obj && typeof obj[k] === 'string' && obj[k].trim()) return obj[k];
  }
  const buscar = v => {
    if (typeof v === 'string') return v.includes('opcoes') ? v : null;
    if (v && typeof v === 'object') {
      for (const x of Object.values(v)) {
        const r = buscar(x);
        if (r) return r;
      }
    }
    return null;
  };
  return buscar(obj);
}

// 2. Ler o JSON, mesmo com cercas de markdown ou texto em volta.
function lerJson(texto) {
  if (!texto) return null;
  let t = String(texto).trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { return JSON.parse(t); } catch (e) { /* tenta o recorte abaixo */ }
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { /* sem JSON válido */ }
  }
  return null;
}

// 3. Validar as opções por família.
const texto = acharTexto(resposta);
const json = lerJson(texto);
const opcoes = [];
let origem = 'ia';

if (!json || !Array.isArray(json.opcoes)) {
  avisos.push('A resposta da IA não pôde ser lida como JSON com "opcoes"; foram usadas opções automáticas');
} else {
  const usadas = new Set();
  const porFamilia = {};
  for (const o of json.opcoes) {
    const c = Number(o && o.candidata);
    if (!Number.isInteger(c) || c < 0 || c >= candidatas.length) {
      avisos.push(`Opção ignorada: candidata "${o && o.candidata}" não existe`);
      continue;
    }
    if (usadas.has(c)) {
      avisos.push(`Opção ignorada: a candidata ${c} apareceu repetida`);
      continue;
    }
    const f = candidatas[c].familia;
    if ((porFamilia[f] || 0) >= maxPorFamilia) {
      avisos.push(`Opção ignorada: a candidata ${c} passa do máximo de ${maxPorFamilia} opções da combinação ${f}`);
      continue;
    }
    usadas.add(c);
    porFamilia[f] = (porFamilia[f] || 0) + 1;
    opcoes.push({
      candidata: c,
      familia: f,
      titulo: String((o && o.titulo) || '').trim(),
      resumo: String((o && o.resumo) || '').trim(),
      tradeoffs: String((o && o.tradeoffs) || '').trim(),
    });
  }
}

// 4. Plano B: texto automático a partir das métricas.
function automatica(indice) {
  const c = candidatasParaIA[indice] || {};
  const m = c.metricas || {};
  const dias = (m.diasComAula || []).join(', ');
  const partes = [`${m.materias} matéria(s), aulas das ${m.primeiraAula} às ${m.ultimaAula}`];
  if (dias) partes.push(`dias com aula: ${dias}`);
  partes.push(m.janelasMinutos ? `${m.janelasMinutos} min de janelas entre as aulas` : 'sem janelas entre as aulas');
  return { candidata: indice, familia: c.familia, titulo: '', resumo: partes.join('. ') + '.', tradeoffs: '' };
}

// Completa cada família até o máximo de opções (as escolhas da IA sempre ficam; o código só preenche o que faltou,
// usando as melhores grades ainda não escolhidas da própria família).
const temIA = opcoes.length > 0;
if (temIA === false) origem = 'automatico';
let acrescentou = false;
for (const f of familias) {
  const alvo = Math.min(f.maxOpcoes || maxPorFamilia, f.candidatas.length);
  const daFamilia = opcoes.filter(o => o.familia === f.familia).length;
  const livres = f.candidatas.filter(c => !opcoes.some(o => o.candidata === c));
  const precisa = Math.max(0, alvo - daFamilia);
  for (const c of livres.slice(0, precisa)) {
    opcoes.push(automatica(c));
    acrescentou = true;
  }
  if (temIA && precisa) {
    avisos.push(daFamilia
      ? `A IA escolheu ${daFamilia} grade(s) da combinação ${f.familia}; o código completou até ${alvo}`
      : `A IA não escolheu nenhuma grade da combinação ${f.familia}; foram acrescentadas as melhores opções dela`);
  }
}
if (temIA && acrescentou) origem = 'ia+automatico';
opcoes.sort((a, b) => a.familia - b.familia);

return [{ json: {
  opcoes,
  origemOpcoes: origem,
  validacaoAvisos: avisos,
  temOpcoes: opcoes.length > 0,
  candidatas,
  familias,
  estagio: gerador.estagio || [],
  tempos: gerador.tempos || [],
  emailAluno: gerador.emailAluno || '',
  prioridadesTexto: gerador.prioridadesTexto || [],
  evitarTexto: gerador.evitarTexto || [],
  observacoes: gerador.observacoes || '',
  avisosAluno: gerador.avisosAluno || [],
  // Problemas das etapas anteriores, para o e-mail explicar quando não há nenhuma grade possível.
  problemas: [...(gerador.preparoErros || []), ...(gerador.geradorErros || []), ...(gerador.preparoAvisos || []), ...(gerador.geradorAvisos || [])],
} }];
